const evaluations = items.flatMap((item) => Array.isArray(item.json.evals) ? item.json.evals : []);
if (evaluations.length === 0) {
  throw new Error('Hydra returned no thornixos/main evaluations');
}
const latest = evaluations[0];
return [{ json: {
  evaluationId: latest.id,
  flake: latest.flake ?? '',
  buildsUrl: `https://forge.guildedthorn.arpa/eval/${latest.id}/builds`,
  evaluationUrl: `https://forge.guildedthorn.arpa/eval/${latest.id}`,
} }];

const metadata = $('Select newest evaluation').first().json;
const builds = items.flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
const expected = [
  'anvil', 'atlas', 'casebook', 'courier', 'forge', 'herald', 'hound',
  'identity', 'loom', 'lure', 'mac', 'mitm', 'nixos', 'oracle', 'pixie',
  'scout', 'sieve', 'soc', 'websites',
].map((host) => `production.${host}`);
const byJob = new Map(builds.map((build) => [build.job, build]));
const states = expected.map((job) => {
  const build = byJob.get(job);
  if (!build) return { job, state: 'missing' };
  if (Number(build.finished) !== 1) return { job, state: 'unfinished' };
  if (Number(build.buildstatus) !== 0) return { job, state: 'failed' };
  const outputs = Object.values(build.buildoutputs ?? {}).filter((output) => output?.path);
  if (outputs.length === 0) return { job, state: 'no-output' };
  return { job, state: 'succeeded' };
});

const failed = states.filter((entry) => ['failed', 'no-output'].includes(entry.state));
const pending = states.filter((entry) => ['missing', 'unfinished'].includes(entry.state));
if (failed.length === 0 && pending.length > 0) return [];

const result = failed.length > 0 ? 'failed' : 'succeeded';
const state = $getWorkflowStaticData('global');
const notificationKey = `${metadata.evaluationId}:${result}`;
if (state.lastNotificationKey === notificationKey) return [];
state.lastNotificationKey = notificationKey;

const revision = String(metadata.flake).match(/[0-9a-f]{40}/)?.[0];
const shortRevision = revision ? revision.slice(0, 8) : `eval ${metadata.evaluationId}`;
const message = result === 'succeeded'
  ? `All ${expected.length} production hosts built successfully for ${shortRevision}. Forge can promote this revision after Cachix verification.`
  : `Hydra evaluation ${metadata.evaluationId} failed: ${failed.map((entry) => `${entry.job} (${entry.state})`).join(', ')}`;

return [{ json: {
  topic: 'thornixos-ops',
  title: result === 'succeeded' ? 'Hydra production gate passed' : 'Hydra production gate failed',
  message,
  priority: result === 'succeeded' ? 3 : 5,
  tags: result === 'succeeded' ? ['heavy_check_mark', 'hydra'] : ['x', 'hydra'],
  click: metadata.evaluationUrl,
} }];
